export class DashboardComponent {
  constructor(fb, authService, soportesService, router) {
    this.fb = fb;
    this.authService = authService;
    this.soportesService = soportesService;
    this.router = router;
    this.currentUser = null;
    this.soportes = [];
    this.loading = false;
    this.error = '';
    this.successMsg = '';
    this.savingNew = false;
    this.selectedSoporte = null;
    this.savingSeguimiento = false;
    this.savingClave = false;
    this.claveError = '';
    this.claveSuccess = '';
    this.exporting = false;
  }
  ngOnInit() {
    this.currentUser = this.authService.currentUser;
    this.nuevaSolicitudForm = this.fb.group({
      motivo: ['', [Validators.required, Validators.minLength(5)]]
    });
    this.seguimientoForm = this.fb.group({
      fechaRespuesta: [''],
      resolvio: [null],
      observaciones: ['']
    });
    this.cambioClaveForm = this.fb.group({
      password: ['', [Validators.required, Validators.minLength(6)]],
      confirmPassword: ['', [Validators.required, Validators.minLength(6)]]
    });
    this.exportForm = this.fb.group({
      desde: ['', Validators.required],
      hasta: ['', Validators.required]
    });
    this.loadSoportes();
  }
  get isAdmin() {
    return this.currentUser?.role === 'admin';
  }
  loadSoportes() {
    this.loading = true;
    this.soportesService.getAll().subscribe({
      next: data => {
        this.soportes = data;
        this.loading = false;
      },
      error: () => {
        this.error = 'Error al cargar los soportes';
        this.loading = false;
      }
    });
  }
  openNuevaSolicitud() {
    this.nuevaSolicitudForm.reset();
    const modal = new bootstrap.Modal(document.getElementById('nuevaSolicitudModal'));
    modal.show();
  }
  guardarNuevaSolicitud() {
    if (this.nuevaSolicitudForm.invalid) {
      this.nuevaSolicitudForm.markAllAsTouched();
      return;
    }
    this.savingNew = true;
    const {
      motivo
    } = this.nuevaSolicitudForm.value;
    this.soportesService.create(motivo).subscribe({
      next: () => {
        this.savingNew = false;
        bootstrap.Modal.getInstance(document.getElementById('nuevaSolicitudModal'))?.hide();
        this.loadSoportes();
        this.showSuccess('Solicitud creada exitosamente');
      },
      error: err => {
        this.savingNew = false;
        this.error = err?.error?.message || 'Error al crear la solicitud';
      }
    });
  }
  openSeguimiento(soporte) {
    this.selectedSoporte = soporte;
    this.seguimientoForm.patchValue({
      fechaRespuesta: soporte.fechaRespuesta ? this.formatDateForInput(soporte.fechaRespuesta) : '',
      resolvio: soporte.resolvio === null || soporte.resolvio === undefined ? '' : soporte.resolvio ? 'true' : 'false',
      observaciones: soporte.observaciones || ''
    });
    const modal = new bootstrap.Modal(document.getElementById('seguimientoModal'));
    modal.show();
  }
  guardarSeguimiento() {
    if (!this.selectedSoporte) return;
    this.savingSeguimiento = true;
    const val = this.seguimientoForm.value;
    const payload = {
      observaciones: val.observaciones || null
    };
    if (val.fechaRespuesta) {
      payload.fechaRespuesta = new Date(val.fechaRespuesta).toISOString();
    }
    if (val.resolvio !== '' && val.resolvio !== null) {
      payload.resolvio = val.resolvio === 'true';
    }
    this.soportesService.update(this.selectedSoporte.id, payload).subscribe({
      next: () => {
        this.savingSeguimiento = false;
        bootstrap.Modal.getInstance(document.getElementById('seguimientoModal'))?.hide();
        this.loadSoportes();
        this.showSuccess('Seguimiento guardado correctamente');
      },
      error: err => {
        this.savingSeguimiento = false;
        this.error = err?.error?.message || 'Error al guardar el seguimiento';
      }
    });
  }
  eliminarSoporte(soporte) {
    if (!confirm(`¿Eliminar la solicitud #${soporte.id}?`)) return;
    this.soportesService.delete(soporte.id).subscribe({
      next: () => {
        this.loadSoportes();
        this.showSuccess('Solicitud eliminada');
      },
      error: err => {
        this.error = err?.error?.message || 'Error al eliminar';
      }
    });
  }
  openCambioClave() {
    this.cambioClaveForm.reset();
    this.claveError = '';
    this.claveSuccess = '';
    const modal = new bootstrap.Modal(document.getElementById('cambioClaveModal'));
    modal.show();
  }
  guardarCambioClave() {
    if (this.cambioClaveForm.invalid) {
      this.cambioClaveForm.markAllAsTouched();
      return;
    }
    const {
      password,
      confirmPassword
    } = this.cambioClaveForm.value;
    if (password !== confirmPassword) {
      this.claveError = 'Las contraseñas no coinciden';
      return;
    }
    this.savingClave = true;
    this.claveError = '';
    this.authService.changePassword(password, confirmPassword).subscribe({
      next: () => {
        this.savingClave = false;
        this.claveSuccess = 'Contraseña cambiada exitosamente';
        this.cambioClaveForm.reset();
      },
      error: err => {
        this.savingClave = false;
        this.claveError = err?.error?.message || 'Error al cambiar la contraseña';
      }
    });
  }
  openExportModal() {
    this.exportForm.reset();
    const modal = new bootstrap.Modal(document.getElementById('exportModal'));
    modal.show();
  }
  exportarExcel() {
    if (this.exportForm.invalid) {
      this.exportForm.markAllAsTouched();
      return;
    }
    this.exporting = true;
    const {
      desde,
