import { Component, OnInit } from '@angular/core';
import { FormBuilder, FormGroup, Validators } from '@angular/forms';
import { Router } from '@angular/router';
import { AuthService } from '../services/auth.service';
import { SoportesService } from '../services/soportes.service';
import { Soporte } from '../models/soporte.model';
import { User } from '../models/user.model';

declare const bootstrap: any;

@Component({
  selector: 'app-dashboard',
  templateUrl: './dashboard.component.html',
})
export class DashboardComponent implements OnInit {
  currentUser: User | null = null;
  soportes: Soporte[] = [];
  loading = false;
  error = '';
  successMsg = '';

  // Nueva solicitud
  nuevaSolicitudForm!: FormGroup;
  savingNew = false;

  // Seguimiento modal
  seguimientoForm!: FormGroup;
  selectedSoporte: Soporte | null = null;
  savingSeguimiento = false;

  // Cambiar contraseña
  cambioClaveForm!: FormGroup;
  savingClave = false;
  claveError = '';
  claveSuccess = '';

  // Export excel (admin)
  exportForm!: FormGroup;
  exporting = false;

  constructor(
    private fb: FormBuilder,
    private authService: AuthService,
    private soportesService: SoportesService,
    private router: Router
  ) {}

  ngOnInit(): void {
    this.currentUser = this.authService.currentUser;

    this.nuevaSolicitudForm = this.fb.group({
      motivo: ['', [Validators.required, Validators.minLength(5)]],
    });

    this.seguimientoForm = this.fb.group({
      fechaRespuesta: [''],
      resolvio: [null],
      observaciones: [''],
    });

    this.cambioClaveForm = this.fb.group({
      password: ['', [Validators.required, Validators.minLength(6)]],
      confirmPassword: ['', [Validators.required, Validators.minLength(6)]],
    });

    this.exportForm = this.fb.group({
      desde: ['', Validators.required],
      hasta: ['', Validators.required],
    });

    this.loadSoportes();
  }

  get isAdmin(): boolean {
    return this.currentUser?.role === 'admin';
  }

  loadSoportes(): void {
    this.loading = true;
    this.soportesService.getAll().subscribe({
      next: (data) => {
        this.soportes = data;
        this.loading = false;
      },
      error: () => {
        this.error = 'Error al cargar los soportes';
        this.loading = false;
      },
    });
  }

  openNuevaSolicitud(): void {
    this.nuevaSolicitudForm.reset();
    const modal = new bootstrap.Modal(
      document.getElementById('nuevaSolicitudModal')
    );
    modal.show();
  }

  guardarNuevaSolicitud(): void {
    if (this.nuevaSolicitudForm.invalid) {
      this.nuevaSolicitudForm.markAllAsTouched();
      return;
    }
    this.savingNew = true;
    const { motivo } = this.nuevaSolicitudForm.value;
    this.soportesService.create(motivo).subscribe({
      next: () => {
        this.savingNew = false;
        bootstrap.Modal.getInstance(
          document.getElementById('nuevaSolicitudModal')
        )?.hide();
        this.loadSoportes();
        this.showSuccess('Solicitud creada exitosamente');
      },
      error: (err) => {
        this.savingNew = false;
        this.error = err?.error?.message || 'Error al crear la solicitud';
      },
    });
  }

  openSeguimiento(soporte: Soporte): void {
    this.selectedSoporte = soporte;
    this.seguimientoForm.patchValue({
      fechaRespuesta: soporte.fechaRespuesta
        ? this.formatDateForInput(soporte.fechaRespuesta)
        : '',
      resolvio: soporte.resolvio === null || soporte.resolvio === undefined
        ? ''
        : soporte.resolvio ? 'true' : 'false',
      observaciones: soporte.observaciones || '',
    });
    const modal = new bootstrap.Modal(
      document.getElementById('seguimientoModal')
    );
    modal.show();
  }

  guardarSeguimiento(): void {
    if (!this.selectedSoporte) return;
    this.savingSeguimiento = true;
    const val = this.seguimientoForm.value;
    const payload: any = {
      observaciones: val.observaciones || null,
    };
    if (val.fechaRespuesta) {
      payload.fechaRespuesta = new Date(val.fechaRespuesta).toISOString();
    }
    if (val.resolvio !== '' && val.resolvio !== null) {
      payload.resolvio = val.resolvio === 'true';
    }

    this.soportesService.update(this.selectedSoporte.id, payload).subscribe({
      next: () => {
        this.savingSeguimiento = false;
        bootstrap.Modal.getInstance(
          document.getElementById('seguimientoModal')
        )?.hide();
        this.loadSoportes();
        this.showSuccess('Seguimiento guardado correctamente');
      },
      error: (err) => {
        this.savingSeguimiento = false;
        this.error = err?.error?.message || 'Error al guardar el seguimiento';
      },
    });
  }

  eliminarSoporte(soporte: Soporte): void {
    if (!confirm(`¿Eliminar la solicitud #${soporte.id}?`)) return;
    this.soportesService.delete(soporte.id).subscribe({
      next: () => {
        this.loadSoportes();
        this.showSuccess('Solicitud eliminada');
      },
      error: (err) => {
        this.error = err?.error?.message || 'Error al eliminar';
      },
    });
  }

  openCambioClave(): void {
    this.cambioClaveForm.reset();
    this.claveError = '';
    this.claveSuccess = '';
    const modal = new bootstrap.Modal(
      document.getElementById('cambioClaveModal')
    );
    modal.show();
  }

  guardarCambioClave(): void {
    if (this.cambioClaveForm.invalid) {
      this.cambioClaveForm.markAllAsTouched();
      return;
    }
    const { password, confirmPassword } = this.cambioClaveForm.value;
    if (password !== confirmPassword) {
      this.claveError = 'Las contraseñas no coinciden';
      return;
    }
    this.savingClave = true;
    this.claveError = '';
    this.authService.changePassword(password, confirmPassword).subscribe({
      next: () => {
        this.savingClave = false;
        this.claveSuccess = 'Contraseña cambiada exitosamente';
        this.cambioClaveForm.reset();
      },
      error: (err) => {
        this.savingClave = false;
        this.claveError = err?.error?.message || 'Error al cambiar la contraseña';
      },
    });
  }

  openExportModal(): void {
    this.exportForm.reset();
    const modal = new bootstrap.Modal(
      document.getElementById('exportModal')
    );
    modal.show();
  }

  exportarExcel(): void {
    if (this.exportForm.invalid) {
      this.exportForm.markAllAsTouched();
      return;
    }
    this.exporting = true;
    const { desde, hasta } = this.exportForm.value;
    this.soportesService.exportExcel(desde, hasta).subscribe({
      next: (blob) => {
        this.exporting = false;
        const url = window.URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `soportes_${desde}_${hasta}.xlsx`;
        a.click();
        window.URL.revokeObjectURL(url);
        bootstrap.Modal.getInstance(
          document.getElementById('exportModal')
        )?.hide();
      },
      error: () => {
        this.exporting = false;
        this.error = 'Error al exportar el archivo';
      },
    });
  }

  logout(): void {
    this.authService.logout();
  }

  formatDate(dateStr: string | null | undefined): string {
    if (!dateStr) return '—';
    return new Date(dateStr).toLocaleString('es-CO', {
      year: 'numeric',
      month: '2-digit',
      day: '2-digit',
      hour: '2-digit',
      minute: '2-digit',
    });
  }

  private formatDateForInput(dateStr: string): string {
    const d = new Date(dateStr);
    const pad = (n: number) => n.toString().padStart(2, '0');
    return `${d.getFullYear()}-${pad(d.getMonth() + 1)}-${pad(d.getDate())}T${pad(d.getHours())}:${pad(d.getMinutes())}`;
  }

  private showSuccess(msg: string): void {
    this.successMsg = msg;
    setTimeout(() => (this.successMsg = ''), 4000);
  }
}
<!-- Navbar -->
<nav class="navbar navbar-expand-lg navbar-dark" style="background: #1e40af;">
  <div class="container-fluid px-4">
    <span class="navbar-brand">
      <i class="bi-chat-dots-fill me-2"></i>SysApolo — Soporte
    </span>
    <div class="d-flex align-items-center gap-3 ms-auto">
      <span class="text-white nav-user-info">
        <i class="bi bi-person-circle me-1"></i>
        {{ currentUser?.nombre }}
        <span class="badge bg-light text-primary ms-1" *ngIf="isAdmin">Admin</span>
      </span>
      <button
        *ngIf="isAdmin"
        class="btn btn-outline-light btn-sm"
        routerLink="/users"
      >
        <i class="bi bi-people me-1"></i>Usuarios
      </button>
      <button class="btn btn-outline-light btn-sm" (click)="logout()">
        <i class="bi bi-box-arrow-right me-1"></i>Salir
      </button>
    </div>
  </div>
</nav>

<!-- Main content -->
<div class="container-fluid px-4 py-4">
  <!-- Alerts -->
  <div class="alert alert-success alert-dismissible py-2" *ngIf="successMsg">
    <i class="bi bi-check-circle me-1"></i>{{ successMsg }}
    <button type="button" class="btn-close py-2" (click)="successMsg = ''"></button>
  </div>
  <div class="alert alert-danger alert-dismissible py-2" *ngIf="error">
    <i class="bi bi-exclamation-circle me-1"></i>{{ error }}
    <button type="button" class="btn-close py-2" (click)="error = ''"></button>
  </div>

  <!-- Card soportes -->
  <div class="card">
    <div class="card-header d-flex justify-content-between align-items-center flex-wrap gap-2">
      <h5 class="mb-0 fw-bold" style="color: #1e40af;">
        <i class="bi bi-clipboard-check me-2"></i>
        Solicitudes de Soporte
      </h5>
      <div class="d-flex gap-2 flex-wrap">
        <!-- Admin: Exportar Excel -->
        <button
          *ngIf="isAdmin"
          class="btn btn-success btn-sm"
          (click)="openExportModal()"
        >
          <i class="bi bi-file-earmark-excel me-1"></i>Exportar Excel
        </button>
        <!-- Cambiar Contraseña -->
        <button class="btn btn-secondary btn-sm" (click)="openCambioClave()">
          <i class="bi bi-key me-1"></i>Cambiar Contraseña
        </button>
        <!-- Nueva Solicitud -->
        <button class="btn btn-primary btn-sm" (click)="openNuevaSolicitud()">
          <i class="bi bi-plus-lg me-1"></i>Nueva Solicitud
        </button>
      </div>
    </div>

    <!-- Loading -->
    <div class="text-center py-5" *ngIf="loading">
      <div class="spinner-border text-primary" role="status"></div>
      <p class="mt-2 text-muted">Cargando soportes...</p>
    </div>

    <!-- Empty state -->
    <div class="text-center py-5" *ngIf="!loading && soportes.length === 0">
      <i class="bi bi-inbox" style="font-size: 3rem; color: #94a3b8;"></i>
      <p class="mt-2 text-muted">No hay solicitudes de soporte</p>
      <button class="btn btn-primary btn-sm" (click)="openNuevaSolicitud()">
        <i class="bi bi-plus-lg me-1"></i>Crear primera solicitud
      </button>
    </div>

    <!-- Table -->
    <div class="table-responsive" *ngIf="!loading && soportes.length > 0">
      <table class="table table-hover mb-0">
        <thead>
          <tr>
            <th>#</th>
            <th>Fecha Solicitud</th>
            <th>Motivo / Descripción</th>
            <th *ngIf="isAdmin">Área</th>
            <th *ngIf="isAdmin">Quien Realiza</th>
            <th>Fecha Respuesta</th>
            <th>Resolvió</th>
            <th>Observaciones</th>
            <th class="text-center">Acciones</th>
          </tr>
        </thead>
        <tbody>
          <tr *ngFor="let s of soportes">
            <td class="text-muted fw-bold">{{ s.id }}</td>
            <td style="white-space: nowrap;">{{ formatDate(s.fechaSolicitud) }}</td>
            <td>
              <span
                class="motivo-text d-block"
                [title]="s.motivo"
              >{{ s.motivo }}</span>
            </td>
            <td *ngIf="isAdmin">{{ s.usuario.area }}</td>
            <td *ngIf="isAdmin">{{ s.usuario.nombre }}</td>
            <td style="white-space: nowrap;">{{ formatDate(s.fechaRespuesta) }}</td>
            <td>
              <span *ngIf="s.resolvio === true" class="badge-si">SI</span>
              <span *ngIf="s.resolvio === false" class="badge-no">NO</span>
              <span *ngIf="s.resolvio === null || s.resolvio === undefined" class="badge-pendiente">Pendiente</span>
            </td>
            <td>
              <span
                class="motivo-text d-block text-muted"
                [title]="s.observaciones || ''"
              >{{ s.observaciones || '—' }}</span>
            </td>
            <td class="text-center" style="white-space: nowrap;">
              <button
                class="btn btn-outline-primary btn-sm me-1"
                title="Asignar Seguimiento"
                (click)="openSeguimiento(s)"
              >
                <i class="bi bi-pencil-square"></i>
              </button>
              <button
                class="btn btn-outline-danger btn-sm"
                title="Eliminar"
                (click)="eliminarSoporte(s)"
              >
                <i class="bi bi-trash"></i>
              </button>
            </td>
          </tr>
        </tbody>
      </table>
    </div>
  </div>
</div>

<!-- ===== MODAL: Nueva Solicitud ===== -->
<div class="modal fade" id="nuevaSolicitudModal" tabindex="-1">
  <div class="modal-dialog">
    <div class="modal-content">
      <div class="modal-header">
        <h5 class="modal-title">
          <i class="bi bi-plus-circle me-2"></i>Nueva Solicitud de Soporte
        </h5>
        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>
      </div>
      <div class="modal-body">
        <form [formGroup]="nuevaSolicitudForm">
          <div class="mb-3">
            <label class="form-label fw-semibold">
              Motivo / Descripción de la solicitud <span class="text-danger">*</span>
            </label>
            <textarea
              class="form-control"
              formControlName="motivo"
              rows="5"
              placeholder="Describa detalladamente el motivo de la solicitud..."
            ></textarea>
            <div
              class="text-danger small mt-1"
              *ngIf="nuevaSolicitudForm.get('motivo')?.touched && nuevaSolicitudForm.get('motivo')?.invalid"
            >
              El motivo es requerido (mínimo 5 caracteres)
            </div>
          </div>
        </form>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Cancelar</button>
        <button
          type="button"
          class="btn btn-primary"
          (click)="guardarNuevaSolicitud()"
          [disabled]="savingNew"
        >
          <span *ngIf="savingNew" class="spinner-border spinner-border-sm me-1"></span>
          <i class="bi bi-save me-1" *ngIf="!savingNew"></i>
          {{ savingNew ? 'Guardando...' : 'Grabar Solicitud' }}
        </button>
      </div>
    </div>
  </div>
</div>

<!-- ===== MODAL: Seguimiento ===== -->
<div class="modal fade" id="seguimientoModal" tabindex="-1">
  <div class="modal-dialog">
    <div class="modal-content">
      <div class="modal-header">
        <h5 class="modal-title">
          <i class="bi bi-clipboard2-check me-2"></i>Asignar Seguimiento
          <small *ngIf="selectedSoporte" class="ms-1 opacity-75">#{{ selectedSoporte.id }}</small>
        </h5>
        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>
      </div>
      <div class="modal-body">
        <!-- Motivo (readonly) -->
        <div class="mb-3" *ngIf="selectedSoporte">
          <label class="form-label fw-semibold text-muted">Motivo de la solicitud</label>
          <p class="form-control-plaintext border rounded p-2 bg-light" style="font-size: 0.9rem;">
            {{ selectedSoporte.motivo }}
          </p>
        </div>

        <form [formGroup]="seguimientoForm">
          <div class="mb-3">
            <label class="form-label fw-semibold">Fecha de Respuesta</label>
            <input
              type="datetime-local"
              class="form-control"
              formControlName="fechaRespuesta"
            />
          </div>
          <div class="mb-3">
            <label class="form-label fw-semibold">¿Resolvió el problema?</label>
            <select class="form-select" formControlName="resolvio">
              <option value="">-- Seleccione --</option>
              <option value="true">SI</option>
              <option value="false">NO</option>
            </select>
          </div>
          <div class="mb-3">
            <label class="form-label fw-semibold">Observaciones</label>
            <textarea
              class="form-control"
              formControlName="observaciones"
              rows="4"
              placeholder="Ingrese las observaciones del seguimiento..."
            ></textarea>
          </div>
        </form>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary" data-bs-dismiss="modal">Cancelar</button>
        <button
          type="button"
          class="btn btn-primary"
          (click)="guardarSeguimiento()"
          [disabled]="savingSeguimiento"
        >
          <span *ngIf="savingSeguimiento" class="spinner-border spinner-border-sm me-1"></span>
          <i class="bi bi-check-lg me-1" *ngIf="!savingSeguimiento"></i>
          {{ savingSeguimiento ? 'Guardando...' : 'Guardar Seguimiento' }}
        </button>
      </div>
    </div>
  </div>
</div>

<!-- ===== MODAL: Cambio de Contraseña ===== -->
<div class="modal fade" id="cambioClaveModal" tabindex="-1">
  <div class="modal-dialog modal-sm">
    <div class="modal-content">
      <div class="modal-header">
        <h5 class="modal-title">
          <i class="bi bi-key me-2"></i>Cambiar Contraseña
        </h5>
        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>
      </div>
      <div class="modal-body">
        <div class="alert alert-danger py-2 small" *ngIf="claveError">
          <i class="bi bi-exclamation-circle me-1"></i>{{ claveError }}
        </div>
        <div class="alert alert-success py-2 small" *ngIf="claveSuccess">
          <i class="bi bi-check-circle me-1"></i>{{ claveSuccess }}
        </div>
        <form [formGroup]="cambioClaveForm">
          <div class="mb-3">
            <label class="form-label fw-semibold">Nueva Contraseña</label>
            <input
              type="password"
              class="form-control"
              formControlName="password"
              placeholder="Mínimo 6 caracteres"
            />
            <div
              class="text-danger small mt-1"
              *ngIf="cambioClaveForm.get('password')?.touched && cambioClaveForm.get('password')?.invalid"
            >
              Mínimo 6 caracteres
            </div>
          </div>
          <div class="mb-3">
            <label class="form-label fw-semibold">Repetir Contraseña</label>
            <input
              type="password"
              class="form-control"
              formControlName="confirmPassword"
              placeholder="Repita la contraseña"
            />
            <div
              class="text-danger small mt-1"
              *ngIf="cambioClaveForm.get('confirmPassword')?.touched && cambioClaveForm.get('confirmPassword')?.invalid"
            >
              Campo requerido
            </div>
          </div>
        </form>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary btn-sm" data-bs-dismiss="modal">Cancelar</button>
        <button
          type="button"
          class="btn btn-primary btn-sm"
          (click)="guardarCambioClave()"
          [disabled]="savingClave"
        >
          <span *ngIf="savingClave" class="spinner-border spinner-border-sm me-1"></span>
          {{ savingClave ? 'Guardando...' : 'Cambiar Contraseña' }}
        </button>
      </div>
    </div>
  </div>
</div>

<!-- ===== MODAL: Exportar Excel (admin) ===== -->
<div class="modal fade" id="exportModal" tabindex="-1">
  <div class="modal-dialog modal-sm">
    <div class="modal-content">
      <div class="modal-header">
        <h5 class="modal-title">
          <i class="bi bi-file-earmark-excel me-2"></i>Exportar a Excel
        </h5>
        <button type="button" class="btn-close" data-bs-dismiss="modal"></button>
      </div>
      <div class="modal-body">
        <form [formGroup]="exportForm">
          <div class="mb-3">
            <label class="form-label fw-semibold">Fecha Desde</label>
            <input type="date" class="form-control" formControlName="desde" />
            <div class="text-danger small mt-1" *ngIf="exportForm.get('desde')?.touched && exportForm.get('desde')?.invalid">
              Requerido
            </div>
          </div>
          <div class="mb-3">
            <label class="form-label fw-semibold">Fecha Hasta</label>
            <input type="date" class="form-control" formControlName="hasta" />
            <div class="text-danger small mt-1" *ngIf="exportForm.get('hasta')?.touched && exportForm.get('hasta')?.invalid">
              Requerido
            </div>
          </div>
        </form>
      </div>
      <div class="modal-footer">
        <button type="button" class="btn btn-secondary btn-sm" data-bs-dismiss="modal">Cancelar</button>
        <button
          type="button"
          class="btn btn-success btn-sm"
          (click)="exportarExcel()"
          [disabled]="exporting"
        >
          <span *ngIf="exporting" class="spinner-border spinner-border-sm me-1"></span>
          <i class="bi bi-download me-1" *ngIf="!exporting"></i>
          {{ exporting ? 'Exportando...' : 'Descargar Excel' }}
        </button>
      </div>
    </div>
  </div>
</div>
